import type { Species, SpeciesSummary } from '@/types';
import index from './generated/species-index.json';

/**
 * All species as lightweight summaries (generated by scripts/build-index.mjs).
 * Use `loadSpecies` / `useFullSpecies` for the complete record.
 */
export const species = index as unknown as SpeciesSummary[];

const byId = new Map(species.map((s) => [s.id, s]));

export function getSpecies(id: string | undefined): SpeciesSummary | undefined {
  return id ? byId.get(id) : undefined;
}

export function speciesInCategory(categoryId: string): SpeciesSummary[] {
  return species.filter((s) => s.category === categoryId || s.secondaryCategories?.includes(categoryId as never));
}

export function speciesInHabitat(habitatId: string): SpeciesSummary[] {
  return species.filter((s) => s.habitats.includes(habitatId as never));
}

/** Related species: explicit links first, then same-category species as a fallback. */
export function relatedSpecies(s: SpeciesSummary | Species, limit = 4): SpeciesSummary[] {
  const out: SpeciesSummary[] = [];
  for (const id of s.related) {
    const r = byId.get(id);
    if (r && r.id !== s.id && !out.includes(r)) out.push(r);
  }
  if (out.length < limit) {
    // Prefer same family, then same order, then same category
    const pools = [
      species.filter((x) => x.taxonomy.family === s.taxonomy.family),
      species.filter((x) => x.taxonomy.order === s.taxonomy.order),
      speciesInCategory(s.category),
    ];
    for (const pool of pools) {
      for (const r of pool) {
        if (out.length >= limit) break;
        if (r.id !== s.id && !out.includes(r)) out.push(r);
      }
    }
  }
  return out.slice(0, limit);
}

/** Deterministic "species of the day" based on the local calendar date. */
export function dailySpecies(date = new Date()): SpeciesSummary {
  const dayOfYear = Math.floor((date.getTime() - new Date(date.getFullYear(), 0, 0).getTime()) / 86400000);
  let h = date.getFullYear() * 1000 + dayOfYear;
  h = ((h >>> 16) ^ h) * 0x45d9f3b;
  h = ((h >>> 16) ^ h) * 0x45d9f3b;
  h = (h >>> 16) ^ h;
  return species[Math.abs(h) % species.length];
}

export function randomSpecies(excludeId?: string): SpeciesSummary {
  const pool = species.filter((s) => s.id !== excludeId);
  return pool[Math.floor(Math.random() * pool.length)];
}

/* ---------------- Lazy full records ---------------- */

const modules = import.meta.glob<Record<string, unknown>>('./species/*.ts');
const fileCache = new Map<string, Promise<Map<string, Species>>>();

function loadFile(file: string): Promise<Map<string, Species>> {
  let p = fileCache.get(file);
  if (!p) {
    const loader = modules[`./species/${file}.ts`];
    if (!loader) return Promise.reject(new Error(`Unknown species file: ${file}`));
    p = loader().then((mod) => {
      const list = Object.values(mod).filter(Array.isArray).flat() as Species[];
      return new Map(list.map((s) => [s.id, s]));
    });
    p.catch(() => fileCache.delete(file));
    fileCache.set(file, p);
  }
  return p;
}

/** Load the complete record for a species (cached per data file). */
export async function loadSpecies(id: string): Promise<Species | undefined> {
  const summary = byId.get(id);
  if (!summary) return undefined;
  const map = await loadFile(summary.file);
  return map.get(id);
}
